TYPE ST_Recipe :
STRUCT
    recipeID : INT;
    ingredientType : INT;
    ingredientRatio : REAL;
    productionTemperature : REAL;
END_STRUCT
END_TYPE

FUNCTION_BLOCK FB_P17
VAR_INPUT
    addRecipe : BOOL;
    deleteRecipe : BOOL;
    modifyRecipe : BOOL;
    queryRecipe : BOOL;
    recipeIn : ST_Recipe;
    recipeID : INT;
    ingredientType : INT;
    ingredientRatio : REAL;
    productionTemperature : REAL;
END_VAR
VAR_OUTPUT
    recipeAdded : BOOL := FALSE;
    recipeDeleted : BOOL := FALSE;
    recipeModified : BOOL := FALSE;
    recipeQueryResult : ST_Recipe;
    error : BOOL := FALSE;
    status : WORD := WORD#16#0000;
END_VAR
VAR_IN_OUT
    recipe : ARRAY[1..10] OF ST_Recipe;
END_VAR
VAR
    initialized : BOOL := FALSE;
    previousAdd : BOOL := FALSE;
    previousDelete : BOOL := FALSE;
    previousModify : BOOL := FALSE;
    previousQuery : BOOL := FALSE;
    riseAdd : BOOL;
    riseDelete : BOOL;
    riseModify : BOOL;
    riseQuery : BOOL;
    operation : INT;
    i : INT;
    foundIndex : INT;
    emptyIndex : INT;
    duplicateID : BOOL;
END_VAR

(*
    每次调用为一个20 ms扫描周期。

    待审冲突及未明确事项：
    1. K1“写入时只能落到空位”与原文“修改已有配方，
       用输入配方替换”冲突。本实现新增只写空位，修改按
       原文覆盖匹配的非空槽；该冲突仍须需求方审定。
    2. I/O表比声明骨架多四个标量输入，全部保留接口。
       原文明示操作使用recipeIn，因此标量输入不参与操作；
       两种输入来源的关系未定义，不暗中进行字段替换。
    3. 请求采用上升沿。并发请求的仲裁未规定，本实现采用
       queryRecipe、addRecipe、deleteRecipe、modifyRecipe顺序，
       每拍最多执行一个操作；其余同拍边沿不排队。
    4. 编号0表示空位，不作为可查询、删除或修改的配方。
       新增仍按原文比较全部槽位：若输入编号0且有空槽，
       报重复8002；若无空槽则报满库8003，不引入新错误码。
    5. 首拍仅建立指定初态，满足C10；首拍请求不执行。
       首拍保持为TRUE的请求将在第二拍识别为上升沿。
    本源码未附编译或逐周期测试验证结论。
*)

recipeAdded := FALSE;
recipeDeleted := FALSE;
recipeModified := FALSE;

IF NOT initialized THEN
    FOR i := 1 TO 10 DO
        recipe[i].recipeID := 0;
    END_FOR;

    recipeQueryResult.recipeID := 0;
    recipeQueryResult.ingredientType := 0;
    recipeQueryResult.ingredientRatio := 0.0;
    recipeQueryResult.productionTemperature := 0.0;

    error := FALSE;
    status := WORD#16#0000;

    previousAdd := FALSE;
    previousDelete := FALSE;
    previousModify := FALSE;
    previousQuery := FALSE;
    initialized := TRUE;
ELSE
    riseAdd := addRecipe AND NOT previousAdd;
    riseDelete := deleteRecipe AND NOT previousDelete;
    riseModify := modifyRecipe AND NOT previousModify;
    riseQuery := queryRecipe AND NOT previousQuery;

    previousAdd := addRecipe;
    previousDelete := deleteRecipe;
    previousModify := modifyRecipe;
    previousQuery := queryRecipe;

    operation := 0;
    IF riseQuery THEN
        operation := 1;
    ELSIF riseAdd THEN
        operation := 2;
    ELSIF riseDelete THEN
        operation := 3;
    ELSIF riseModify THEN
        operation := 4;
    END_IF;

    IF operation <> 0 THEN
        (* 无新边沿时不改error/status，保持上一次结果。 *)
        error := FALSE;
        status := WORD#16#0000;

        foundIndex := 0;
        emptyIndex := 0;
        duplicateID := FALSE;

        FOR i := 1 TO 10 DO
            IF recipe[i].recipeID = 0 THEN
                IF emptyIndex = 0 THEN
                    emptyIndex := i;
                END_IF;
            END_IF;

            IF recipe[i].recipeID = recipeIn.recipeID THEN
                duplicateID := TRUE;

                IF (recipeIn.recipeID <> 0) AND
                   (foundIndex = 0) THEN
                    foundIndex := i;
                END_IF;
            END_IF;
        END_FOR;

        CASE operation OF
            1:
                (* 查询不改变数据库；失败时保持上次查询结果。 *)
                IF foundIndex = 0 THEN
                    error := TRUE;
                    status := WORD#16#8001;
                ELSE
                    recipeQueryResult := recipe[foundIndex];
                END_IF;

            2:
                (* 重复检查优先于满库检查。 *)
                IF duplicateID THEN
                    error := TRUE;
                    status := WORD#16#8002;
                ELSIF emptyIndex = 0 THEN
                    error := TRUE;
                    status := WORD#16#8003;
                ELSE
                    recipe[emptyIndex] := recipeIn;
                    recipeAdded := TRUE;
                END_IF;

            3:
                IF foundIndex = 0 THEN
                    error := TRUE;
                    status := WORD#16#8004;
                ELSE
                    (* 原文仅要求清除编号，其余字段保持。 *)
                    recipe[foundIndex].recipeID := 0;
                    recipeDeleted := TRUE;
                END_IF;

            4:
                IF foundIndex = 0 THEN
                    error := TRUE;
                    status := WORD#16#8005;
                ELSE
                    (* 按原文替换已有配方；K1冲突见上述待审说明。 *)
                    recipe[foundIndex] := recipeIn;
                    recipeModified := TRUE;
                END_IF;
        END_CASE;
    END_IF;
END_IF;

END_FUNCTION_BLOCK
